// Version profiles and catalogs generated by scripts/build-catalog.mjs from pinned
// Mojang sources. Nothing here is hand-mapped; regenerate instead of editing JSON.
import profileData from './catalogs/profiles.json';
import type { Asset, Edit, Edition, Project } from './domain';

type Sources = Record<string, string>;
export type Profile = {
  edition: Edition; version: string; label: string; order: string; catalog: string; releaseTime?: string;
  java?: { resourceFormat: [number, number] };
  bedrock?: { sampleVersion: string; engineVersion: [number, number, number] };
  sources: Sources; counts: { blocks: number; slots: number; editableSlots: number; sounds: number };
  verification: 'source-generated';
};
type RawSlot = { path: string; label: string; faces: string[]; preview?: string; unavailable?: string; vanillaFormat?: string };
type RawCatalog = {
  schema: 1; edition: Edition;
  blocks: { id: string; name: string; slots: RawSlot[]; unavailable?: string }[];
  sounds: { event: string; name: string; category: string; clips: number; subtitle?: string; stream?: boolean; attenuation?: number }[];
};

/** Sorted newest first within each edition. */
export const profiles = profileData as unknown as Profile[];
export const findProfile = (edition: Edition, version: string) => profiles.find(p => p.edition === edition && p.version === version);
export const latestVersion = (edition: Edition) => profiles.find(p => p.edition === edition)!.version;

export const UNAVAILABLE: Record<string, string> = {
  special: 'Drawn by special game code (entity, fluid, or block-entity renderer). Editing is not supported yet.',
  animated: 'Animated texture. Editing animated textures is not supported yet.',
  nonSquare: 'Non-square texture layout. Only square textures can be edited for now.',
  sharedVariant: 'Mojang’s sample maps this block through a texture key shared by several blocks with multiple variant files, and does not record which variant this block uses.',
  missing: 'The pinned source defines no texture for this block.',
  bedrockSound: 'Bedrock sound replacement is not enabled yet.',
};
const UNAVAILABLE_CATEGORY: Record<string, string> = { special: 'Special rendering (not editable)', animated: 'Animated (not editable)', nonSquare: 'Non-square (not editable)', sharedVariant: 'Unmapped variant (not editable)', missing: 'No texture (not editable)' };

const loaders = import.meta.glob<RawCatalog>('./catalogs/*/*.json', { import: 'default' });
const cache = new Map<string, Promise<Asset[]>>();

/** Archive-relative paths are catalog controlled; sound clips use a reserved folder. */
export const soundSlot = (event: string) => `sounds/${event.replaceAll('.', '/')}.ogg`;

function toAssets(raw: RawCatalog, edition: Edition): Asset[] {
  const users = new Map<string, Set<string>>();
  for (const b of raw.blocks) for (const s of b.slots) if (!s.unavailable) { if (!users.has(s.path)) users.set(s.path, new Set()); users.get(s.path)!.add(b.name); }
  const textures: Asset[] = raw.blocks.flatMap(b => {
    if (!b.slots.length) return [{ id: b.id, name: b.name, kind: 'texture' as const, path: `unavailable:${b.id}`, category: UNAVAILABLE_CATEGORY[b.unavailable ?? 'missing'], unavailable: UNAVAILABLE[b.unavailable ?? 'missing'] }];
    return b.slots.map(s => {
      const shared = [...users.get(s.path) ?? []].filter(n => n !== b.name);
      const asset: Asset = { id: b.id, name: b.slots.length === 1 ? b.name : `${b.name} - ${s.label}`, kind: 'texture', path: s.path, category: s.unavailable ? UNAVAILABLE_CATEGORY[s.unavailable] : 'Blocks', faces: s.faces };
      if (shared.length) asset.shared = shared;
      if (s.preview) asset.preview = s.preview;
      if (s.unavailable) asset.unavailable = UNAVAILABLE[s.unavailable];
      if (s.vanillaFormat) asset.vanillaFormat = s.vanillaFormat;
      return asset;
    });
  });
  const sounds: Asset[] = raw.sounds.map(s => {
    const asset: Asset = { id: s.event, event: s.event, name: s.name, kind: 'sound', path: soundSlot(s.event), category: s.category, codec: 'Ogg Vorbis', clips: s.clips, mono: !/^(music|ui)\./.test(s.event) };
    if (s.subtitle) asset.subtitle = s.subtitle;
    if (s.stream) asset.stream = true;
    if (s.attenuation != null) asset.attenuation = s.attenuation;
    if (edition === 'bedrock') asset.unavailable = UNAVAILABLE.bedrockSound;
    return asset;
  });
  return [...textures.sort((a, b) => a.name.localeCompare(b.name)), ...sounds.sort((a, b) => a.name.localeCompare(b.name))];
}

export function loadCatalog(edition: Edition, version: string): Promise<Asset[]> {
  const profile = findProfile(edition, version);
  if (!profile) return Promise.reject(Error(`${edition} ${version} is not a supported profile.`));
  const key = `./catalogs/${profile.catalog}.json`;
  if (!cache.has(key)) {
    const loader = loaders[key];
    if (!loader) return Promise.reject(Error(`Catalog data for ${profile.label} is missing from this build.`));
    const pending = loader().then(raw => toAssets(raw, edition));
    pending.catch(() => cache.delete(key));
    cache.set(key, pending);
  }
  return cache.get(key)!;
}

/** Textures are identified by their destination file (shared files are one edit); sounds by event. */
export function findAsset(assets: Asset[], edit: Pick<Edit, 'target' | 'slot'>): Asset | undefined {
  return assets.find(a => !a.unavailable && a.path === edit.slot && (a.kind === 'texture' || a.id === edit.target));
}
export function matchesEdit(asset: Asset, edit: Pick<Edit, 'target' | 'slot'>) {
  return edit.slot === asset.path && (asset.kind === 'texture' || edit.target === asset.id);
}

/** Marks edits that do not map to this catalog as unresolved. Edits are never removed. */
export function reconcile(project: Project, assets: Asset[]): Project {
  const label = findProfile(project.edition, project.gameVersion)?.label ?? `${project.edition} ${project.gameVersion}`;
  let changed = false;
  const edits = project.edits.map(e => {
    if (!e.valid) return e;
    const asset = assets.find(a => matchesEdit(a, e));
    if (asset && !asset.unavailable) return e;
    changed = true;
    return { ...e, valid: false, message: `Unresolved: ${e.slot ?? e.target} is not an editable ${label} target${asset?.unavailable ? ` (${asset.unavailable})` : ''}. Remove it, or switch to a version that has it.` };
  });
  return changed ? { ...project, edits } : project;
}
